const incoming = $input.first()?.json ?? {};
const icpPackId = incoming.icp_pack_id || null;
const icpPackSlug = incoming.icp_pack_slug || null;
if (!icpPackId && !icpPackSlug) throw new Error('SEGURIDAD: icp_pack_id o icp_pack_slug es obligatorio (sin valor por defecto). Abortando.');
const filter = icpPackId ? `id=eq.${icpPackId}` : `slug=eq.${icpPackSlug}`;
return [{json:{ icp_pack_url: `https://uwquwjmiofixzugttals.supabase.co/rest/v1/icp_packs?${filter}&select=id,slug,status&limit=1` }}];

const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const row = Array.isArray(body) ? body[0] : body;
if (status < 200 || status >= 300 || !row || !row.id) throw new Error(`ICP Pack no encontrado (HTTP ${status || 'unknown'}).`);
if (row.status !== 'active') throw new Error(`ICP Pack '${row.slug}' esta en estado '${row.status}', no 'active'.`);
return [{ json: { icp_pack_id: row.id, icp_pack_slug: row.slug } }];

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const EXPECTED_ICP_PACK_SLUG = 'atacama-labs-test';
const row = $json;
if (row.icp_pack_id !== EXPECTED_ICP_PACK_ID || row.icp_pack_slug !== EXPECTED_ICP_PACK_SLUG) {
  throw new Error(`SEGURIDAD: ICP pack resuelto (${row.icp_pack_slug} / ${row.icp_pack_id}) NO coincide con el esperado (${EXPECTED_ICP_PACK_SLUG} / ${EXPECTED_ICP_PACK_ID}). Abortando antes de leer o escribir nada.`);
}
return [{ json: { ...row, EXPECTED_ICP_PACK_ID } }];

const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
if (status < 200 || status >= 300) throw new Error(`Fetch draftable prospects failed: HTTP ${status || 'unknown'}`);
const rows = Array.isArray(body) ? body : [];
if (!rows.length) return [{ json: { _no_work: true } }];
return rows.map(r => ({ json: { ...r, _no_work: false } }));

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const item = $json;
if (item.icp_pack_id !== EXPECTED_ICP_PACK_ID) throw new Error(`SEGURIDAD: prospect ${item.id} tiene icp_pack_id (${item.icp_pack_id}) distinto del esperado (${EXPECTED_ICP_PACK_ID}). Abortando.`);
return { json: item };

const prospect = $('Assert Expected Pack (before fetch)').item.json;
const res = $json;
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const rows = status >= 200 && status < 300 && Array.isArray(body) ? body : [];
const hasActiveDraft = rows.some(r => ['draft', 'scheduled', 'sent', 'delivered', 'replied'].includes(r.status));
return [{ json: { prospect, has_draft: hasActiveDraft } }];

const prospect = $('Needs Draft?').item.json.prospect;
const accRes = $('Fetch Account And Research').item.json ?? {};
const account = (Array.isArray(accRes.body) ? accRes.body[0] : null) || {};
const resRes = $json ?? {};
const researchRows = Number(resRes.statusCode) >= 200 && Number(resRes.statusCode) < 300 && Array.isArray(resRes.body) ? resRes.body : [];

if (!researchRows.length) {
  return [{ json: { prospect, account, skip: true, skip_reason: 'Sin evidencia real en research -- no se genera draft sin evidencia (contracts/PROSPECTING.md: no inventar dolor).' } }];
}

const evidenceList = researchRows.slice(0, 6).map((r, i) => `[${i + 1}] (${r.research_type}) ${r.finding} -- ${r.source_url}`).join('\n');

const system = `Eres el redactor de borradores de Atacama Labs (test). SOLO puedes citar hechos presentes en la evidencia entregada. NUNCA inventes dolores, cifras o afirmaciones que no esten en la evidencia. Este es un BORRADOR -- nunca se envia automaticamente. Responde EXCLUSIVAMENTE en JSON: {"subject":"...","message":"...","evidence_ids_used":[1,2]} sin texto fuera del JSON.`;
const prompt = `Empresa: ${account.name || prospect.account_id}
Angulo comercial detectado: ${prospect.commercial_angle || 'sin angulo especifico'}

EVIDENCIA DISPONIBLE (cita al menos una, referenciando su numero):
${evidenceList}

Escribe un borrador de primer contacto breve (max 120 palabras), profesional, en español de Chile, mencionando explicitamente al menos una observación de la evidencia (no genérico). No prometas resultados. No inventes nada que no este en la evidencia.`;

return [{ json: { prospect, account, skip: false, system_prompt: system, user_prompt: prompt, evidence_rows: researchRows } }];

const base = $('Build Draft Prompt').item.json;
const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const errors = [];
if (status < 200 || status >= 300) errors.push(`OpenClaw HTTP ${status || 'unknown'}`);
let content = body?.choices?.[0]?.message?.content;
if (typeof content !== 'string') errors.push('OpenClaw response missing content');
let parsed = null;
if (typeof content === 'string') {
  let cleaned = content.trim().replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/\s*```$/, '').trim();
  const first = cleaned.indexOf('{'), last = cleaned.lastIndexOf('}');
  if (first >= 0 && last > first) cleaned = cleaned.slice(first, last + 1);
  try { parsed = JSON.parse(cleaned); } catch (e) { errors.push(`Invalid JSON: ${e.message}`); }
}
if (!parsed || typeof parsed !== 'object') parsed = {};
const subject = typeof parsed.subject === 'string' ? parsed.subject.trim().slice(0, 200) : null;
const message = typeof parsed.message === 'string' ? parsed.message.trim().slice(0, 3000) : null;
const valid = errors.length === 0 && subject && message;
return [{ json: { ...base, valid, parse_errors: errors, subject, message } }];

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
if ($json.prospect.icp_pack_id !== EXPECTED_ICP_PACK_ID) throw new Error(`SEGURIDAD: prospect ${$json.prospect.id} icp_pack_id (${$json.prospect.icp_pack_id}) distinto del esperado (${EXPECTED_ICP_PACK_ID}). Abortando antes de insertar draft.`);
return $input.all();

let s = $json;
if (s.iteration_result) return [{ json: s }];
const res = s;
const status = Number(res.statusCode ?? 0);
const ok = status >= 200 && status < 300;
return [{ json: { iteration_result: { prospect_id: $('Parse Draft Result').item.json.prospect.id, status: ok ? 'draft_created' : 'error', subject: $('Parse Draft Result').item.json.subject } } }];

const items = $input.all().map(i => i.json.iteration_result).filter(Boolean);
const count = k => items.filter(x => x.status === k).length;
return [{ json: { workflow: 'Atacama Labs - 05 Outreach Draft (test)', processed: items.length, drafts_created: count('draft_created'), skipped: count('skipped') + count('invalid'), results: items } }];
